#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

struct Uczen {
    string imie;
    double srednia;
};

int main() {
    ifstream plik("egzamin.txt");
    vector<Uczen> uczniowie;
    string imie;
    int mat, fiz, inf;
    while (plik >> imie >> mat >> fiz >> inf) {
        double sr = (mat * 3 + fiz * 2 + inf * 5) / 10.0;
        uczniowie.push_back({imie, sr});
    }

    cout << fixed << setprecision(2);
    cout << "a) Srednie wazone:" << endl;
    for (auto &u : uczniowie) {
        cout << "   " << u.imie << ": " << u.srednia << endl;
    }

    sort(uczniowie.begin(), uczniowie.end(), [](const Uczen &a, const Uczen &b) {
        return a.srednia > b.srednia;
    });

    cout << endl << "b) Ranking:" << endl;
    for (int i = 0; i < (int)uczniowie.size(); i++) {
        cout << "   " << i + 1 << ". " << uczniowie[i].imie << ": " << uczniowie[i].srednia << endl;
    }

    cout << endl << "c) Najlepszy uczen: " << uczniowie[0].imie << endl;
    return 0;
}
```

